(() => {
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
  document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.menu').setAttribute('aria-label','Abrir menu')));
  const progress=document.querySelector('.reading-progress');
  let ticking=false;
  function updateScroll(){const distance=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${distance>0?scrollY/distance:0})`;document.body.classList.toggle('is-scrolled',scrollY>15);ticking=false}
  addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateScroll);ticking=true}},{passive:true});addEventListener('resize',updateScroll);updateScroll();
  const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;reveal.unobserve(entry.target);if(!reduced.matches)entry.target.animate([{opacity:0,transform:'translateY(25px)'},{opacity:1,transform:'translateY(0)'}],{duration:800,easing:'cubic-bezier(.22,1,.36,1)',delay:Number(entry.target.dataset.delay||0)})}),{threshold:.08});
  document.querySelectorAll('.about-copy,.fruit-photo,.product-grid>div,.films-heading,.film-carousel,.club>h2,.club>p,.steps article,.duo>section,.review-title,.buy-heading,.order').forEach((el,i)=>{el.dataset.delay=el.matches('.steps article')?String((i%3)*70):'0';reveal.observe(el)});
  function carousel(track,items,onChange){let current=0,frame,previousWidth=track.clientWidth;const clamp=n=>Math.max(0,Math.min(items.length-1,n));function refresh(){const next=clamp(Math.round(track.scrollLeft/Math.max(1,track.clientWidth)));if(next!==current){current=next;onChange(current)}items.forEach((el,i)=>{el.inert=i!==current;el.setAttribute('aria-hidden',i!==current)});return current}function go(n){const target=clamp(n);track.scrollTo({left:target*track.clientWidth,behavior:reduced.matches?'instant':'smooth'})}track.addEventListener('scroll',()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(refresh)},{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(current+(e.key==='ArrowRight'?1:-1))}if(e.key==='Home'){e.preventDefault();go(0)}if(e.key==='End'){e.preventDefault();go(items.length-1)}});new ResizeObserver(()=>{if(track.clientWidth!==previousWidth){previousWidth=track.clientWidth;track.scrollTo({left:current*track.clientWidth,behavior:'instant'})}}).observe(track);onChange(0);refresh();return {go,index:()=>current}}
  const productTrack=document.querySelector('.product-track');
  const product=carousel(productTrack,[...productTrack.children],index=>{document.querySelector('.gallery-count').textContent=`0${index+1} / 03`;document.querySelectorAll('[data-product-step]').forEach(b=>b.disabled=Number(b.dataset.productStep)<0?index===0:index===2)});
  document.querySelectorAll('[data-product-step]').forEach(b=>b.addEventListener('click',()=>product.go(product.index()+Number(b.dataset.productStep))));
  const filmTrack=document.querySelector('.film-track'),videos=[...filmTrack.querySelectorAll('video')],status=document.querySelector('.film-status');
  const films=carousel(filmTrack,[...filmTrack.children],index=>{videos.forEach((v,i)=>{if(i!==index)v.pause()});document.querySelectorAll('[data-film]').forEach(b=>{const active=Number(b.dataset.film)===index;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active)});document.querySelector('.film-counter').textContent=`0${index+1} / 03`;document.querySelectorAll('[data-film-step]').forEach(b=>b.disabled=Number(b.dataset.filmStep)<0?index===0:index===2);status.textContent=''});
  document.querySelectorAll('[data-film]').forEach(b=>b.addEventListener('click',()=>films.go(Number(b.dataset.film))));document.querySelectorAll('[data-film-step]').forEach(b=>b.addEventListener('click',()=>films.go(films.index()+Number(b.dataset.filmStep))));
  document.querySelectorAll('[data-play]').forEach(b=>{const video=videos[Number(b.dataset.play)];b.addEventListener('click',async()=>{if(!video.paused){video.pause();return}try{await video.play()}catch{status.textContent='Não foi possível iniciar o filme. Use os controles do vídeo para tentar novamente.'}});video.addEventListener('play',()=>{videos.forEach(other=>{if(other!==video)other.pause()});b.innerHTML='<span aria-hidden="true">Ⅱ</span> Pausar filme'});const reset=()=>{b.innerHTML='<span aria-hidden="true">▶</span> Assistir filme'};video.addEventListener('pause',reset);video.addEventListener('ended',reset);video.addEventListener('error',()=>{status.textContent='Este vídeo não pôde ser carregado. Você pode tentar outro filme.'})});
  const visibility=new IntersectionObserver(entries=>{entries.forEach(e=>{if(!e.isIntersecting)videos.forEach(v=>v.pause())})},{threshold:0});visibility.observe(document.querySelector('.film-carousel'));document.addEventListener('visibilitychange',()=>{if(document.hidden)videos.forEach(v=>v.pause())});
  // Os relatos continuam ilustrativos; a troca ganha uma transição discreta.
  document.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',()=>{if(!reduced.matches)document.querySelectorAll('.review-cards article').forEach((el,i)=>el.animate([{opacity:.3,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,delay:i*55,easing:'ease-out'}))}));
})();
